/* @lc app=leetcode id=3710 lang=kotlin */ class Solution { fun man(a: IntArray, b: IntArray): Int = Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]) fun bip(p: Array<IntArray>, D: Int): Boolean = IntArray(p.size) { -1 }.let { col -> p.indices.forEach { s -> if (col[s] == -1) col.set(s, 0).let { generateSequence(listOf(s)) { f -> f.flatMap { u -> p.indices.filter { v -> col[v] == -1 && man(p[u], p[v]) < D }.onEach { v -> col[v] = 1 - col[u] } }.takeIf { it.isNotEmpty() } }.count() } }.let { p.indices.all { u -> (u + 1 until p.size).all { v -> !(man(p[u], p[v]) < D && col[u] == col[v]) } } } } fun maxPartitionFactor(points: Array<IntArray>): Int = if (points.size == 2) 0 else points.indices.flatMap { i -> (i + 1 until points.size).map { j -> man(points[i], points[j]) } }.distinct().sorted().let { ds -> generateSequence(0 to ds.size - 1) { (lo, hi) -> if (lo >= hi) null else ((lo + hi + 1) / 2).let { mid -> if (bip(points, ds[mid])) mid to hi else lo to mid - 1 } }.last().first.let { ds[it] } } }